  7 function Find-MarkerFile {
  8     param(
  9         [string]$StartDir = (Get-Location).Path,
 10         [int]$MaxDepth = 20
 11     )
 12 
 13     $dir = $StartDir
 14     $depth = 0
 15     while ($dir -and $depth -lt $MaxDepth) {
 16         $candidate = Join-Path $dir $script:MARKER_FILENAME
 17         if (Test-Path $candidate) {
 18             return $candidate
 19         }
 20         $parent = Split-Path $dir -Parent
 21         if ($parent -eq $dir) { break }
 22         $dir = $parent
 23         $depth++
 24     }
 25 
 26     throw "No marker file ($script:MARKER_FILENAME) found walking up from $StartDir"
 27 }
