 29 function Get-MarkerField {
 30     param(
 31         [Parameter(Mandatory)][string]$MarkerFile,
 32         [Parameter(Mandatory)][string]$FieldName
 33     )
 34 
 35     $content = Get-Content $MarkerFile -Raw
 36     foreach ($line in ($content -split "`n")) {
 37         if ($line -match "^${FieldName}:\s*(.+)$") {
 38             $value = $Matches[1].Trim()
 39             # Remove surrounding quotes if present
 40             if ($value.StartsWith('"') -and $value.EndsWith('"')) {
 41                 $value = $value.Substring(1, $value.Length - 2)
 42             }
 43             return $value
 44         }
 45     }
 46     return $null
 47 }
