 49 function Get-MarkerFileSnapshot {
 50     param(
 51         [string]$StartDir = (Get-Location).Path,
 52         [string]$MarkerFile
 53     )
 54 
 55     $path = $MarkerFile
 56     if (-not $path) {
 57         $path = Find-MarkerFile -StartDir $StartDir
 58     }
 59 
 60     $resolved = (Resolve-Path -LiteralPath $path).ProviderPath
 61     $item = Get-Item -LiteralPath $resolved
 62     return [ordered]@{
 63         markerFilePath = $resolved
 64         markerLastWriteUtc = $item.LastWriteTimeUtc.ToString('O')
 65     }
