 68 function Get-MarkerEndpoint {
 69     param(
 70         [Parameter(Mandatory)][string]$MarkerFile,
 71         [Parameter(Mandatory)][string]$EndpointName
 72     )
 73 
 74     $inEndpoints = $false
 75     foreach ($line in (Get-Content $MarkerFile)) {
 76         if ($line -match '^endpoints:') {
 77             $inEndpoints = $true
 78             continue
 79         }
 80         if ($inEndpoints -and $line -match '^\S') {
 81             break
 82         }
 83         if ($inEndpoints -and $line -match "^\s+${EndpointName}:\s*(.+)$") {
 84             return $Matches[1].Trim()
 85         }
 86     }
 87     return $null
 88 }
