195 function Invoke-FullBootstrap {
196     param(
197         [string]$StartDir = (Get-Location).Path
198     )
199 
200     # Find marker
201     try {
202         $markerFile = Find-MarkerFile -StartDir $StartDir
203     } catch {
204         Write-Error "MCP_UNTRUSTED: No marker file found"
205         return $false
206     }
207 
208     # Verify signature
209     if (-not (Test-MarkerSignature -MarkerFile $markerFile)) {
210         Write-Error "MCP_UNTRUSTED: Signature verification failed"
211         return $false
212     }
213 
214     # Health nonce check
215     $baseUrl = Get-MarkerField -MarkerFile $markerFile -FieldName 'baseUrl'
216     $nonce = "nonce-$(Get-Date -Format 'yyyyMMddHHmmss')-$PID"
217     try {
218         $response = Invoke-RestMethod -Uri "$baseUrl/health?nonce=$nonce" -TimeoutSec 5
219         if ($response.nonce -ne $nonce) {
220             Write-Error "MCP_UNTRUSTED: Nonce verification failed"
221             return $false
222         }
223     } catch {
224         Write-Error "MCP_UNTRUSTED: Health check failed - $_"
225         return $false
226     }
227 
228     return $true
229 }

